        screenSize: CGSize,
        isExpanded: Bool,
        spacing: CGFloat,
        columns: Int,
        gridColumns: [GridItem],
        groupedSounds: [String: [DisplayableSound]]
    ) -> some View {
        let focusGroup = activeFocusGroup
        let semanticMode = activeSemanticFocusMode
        let allSoundsFlat = categoryOrder.flatMap { groupedSounds[$0] ?? [] }
