        return VStack(alignment: .leading, spacing: spacing * 2) {
            activeSoundsSection(
                activeSounds: activeSounds,
                semanticMode: semanticMode,
                isExpanded: isExpanded,
                spacing: spacing,
                columns: columns,
                gridColumns: gridColumns,
                screenSize: screenSize
            )

            categorySoundsSections(
                groupedSounds: groupedSounds,
                activeSoundIds: activeSoundIds,
                hasActiveMode: !activeSounds.isEmpty,
                isExpanded: isExpanded,
                spacing: spacing,
                columns: columns,
                gridColumns: gridColumns,
                screenSize: screenSize
            )

            moreSoundsSection(
                isExpanded: isExpanded,
                spacing: spacing,
                columns: columns,
                gridColumns: gridColumns,
                screenSize: screenSize
            )
        }
    }

    private func activeDisplayableSounds(
        allSounds: [DisplayableSound],
        focusGroup: FocusGroup?,
        semanticMode: SemanticFocusMode?
