            return
        }

        let displayToLabel: [String: String] = Dictionary(
            uniqueKeysWithValues: allLabels.map { label in
                (SoundIdentifier.displayNameForLabel(label), label)
            }
        )

        var matchedSounds = Set<SoundIdentifier>()
        for displayName in requestedDisplayNames {
            if let label = displayToLabel[displayName] {
                matchedSounds.insert(SoundIdentifier(labelName: label))
            } else {
                Logger.log("SiriRequestedSoundCategory: no match for '\(displayName)'")
            }
        }

        guard !matchedSounds.isEmpty else {
            Logger.log("SiriRequestedSoundCategory: no matching sounds found")
            return
        }

        // Merge with current selection (add requested sounds, don't remove existing)
        let updatedSounds = selectedSounds.union(matchedSounds)
        updateSelectedSounds(updatedSounds)

        // Persist to UserDefaults
        let labelNames = updatedSounds.map { $0.labelName }
        UserDefaults.standard.set(labelNames, forKey: "selectedSounds")

        Logger.log("Siri category applied: added \(matchedSounds.count) sounds, total \(updatedSounds.count)")
