    // Update sensitivity threshold without restarting detection
    // Note: slider value is inverted - higher slider = more sensitive = lower detection threshold
    func updateSensitivity(threshold: Double) {
        self.hapticThreshold = threshold
        UserDefaults.standard.set(threshold, forKey: "HapticThreshold")
        SharedStorage.lastAudioEvent = "Sensitivity Updated: \(Int(threshold * 100))%"

        // Invert threshold: higher slider = more sensitive = lower detection threshold
        // Minimum threshold of 0.15 to filter out background noise
        let actualThreshold = max(0.15, 1.0 - threshold)

        // Update the thresholds in all detection states without restarting
        for i in 0..<detectionStates.count {
            let (soundIdentifier, _) = detectionStates[i]
            let newState = DetectionState(
                presenceThreshold: actualThreshold,
                absenceThreshold: actualThreshold * 0.6,
                presenceMeasurementsToStartDetection: 2,
                absenceMeasurementsToEndDetection: 30
            )
            detectionStates[i] = (soundIdentifier, newState)
        }
    }

    // Update selected sounds without restarting detection
    func updateSelectedSounds(_ sounds: Set<SoundIdentifier>) {
        self.selectedSounds = sounds
        SharedStorage.lastAudioEvent = "Updated Selected Sounds: \(sounds.count)"

        // Clear current detected sounds that are no longer selected
        detectedSounds = detectedSounds.filter { selectedSounds.contains($0.soundIdentifier) }
    }
