    /// Handles interrupted transactions and retries
    func handleInterruptedTransactions() async {
        LogManager.shared.addLog("Checking for interrupted transactions")

        // Skip for testing environments
        if environment == .testFlight || environment == .xcodeDebug {
            return
        }

        // Look for any unfinished transactions
        for await result in Transaction.unfinished {
            if case .verified(let transaction) = result {
                if transaction.revocationDate == nil {
                    LogManager.shared.addLog("Processing unfinished transaction: \(transaction.productID)")

                    // Update subscription status on main thread
                    await MainActor.run {
                        unlockSubscription(for: transaction.productID)
                    }

                    // Finish the transaction
                    await transaction.finish()

                    // Force refresh subscription state
                    await refreshSubscriptionState()
                }
            }
        }

        // Also check all transactions to ensure we don't miss anything
        for await result in Transaction.all {
            if case .verified(let transaction) = result {
                if transaction.revocationDate == nil &&
                   (transaction.productID == monthlyProductID || transaction.productID == yearlyProductID) {
                    // Check if transaction is still active
                    if let expirationDate = transaction.expirationDate, expirationDate > Date() {
                        LogManager.shared.addLog("Found active transaction: \(transaction.productID)")

                        // Update subscription status on main thread
                        await MainActor.run {
                            unlockSubscription(for: transaction.productID)
                        }
                    }
                }
            }
        }
    }

