struct TapRecord: Codable, Identifiable {
    var id = UUID()
    let soundName: String
    let timestamp: Double // Store as timeIntervalSince1970
    var confidence: Double = 0.0 // Detection confidence (0.0 - 1.0)

    // Alert feedback fields
    var userConfirmed: Bool? = nil // nil = no response, true = heard it, false = didn't hear
    var wasFalsePositive: Bool? = nil // true if user marked as wrong sound
    var feedbackNote: String? = nil // Optional user comment
    var feedbackTimestamp: Double? = nil // When feedback was provided

    // Computed property to get Date object
    var date: Date {
        return Date(timeIntervalSince1970: timestamp)
    }

    // Custom coding keys to ensure ID is properly coded
    enum CodingKeys: String, CodingKey {
        case id, soundName, timestamp, confidence
        case userConfirmed, wasFalsePositive, feedbackNote, feedbackTimestamp
    }
}

