    private func checkVolumeLevel() {
        // Read outputVolume without changing audio session category
        // Changing to .playback would break an active .playAndRecord mic session
        let audioSession = AVAudioSession.sharedInstance()
        currentVolume = audioSession.outputVolume

        Logger.log("Current volume: \(currentVolume)")

        // Show warning if volume is less than 80% (0.8)
        if currentVolume < 0.8 {
            showVolumeWarning = true
        }
    }

    private func setupVolumeObserver() {
        // Prevent duplicate observers if onAppear fires repeatedly.
        if volumeObserver != nil { return }

        // Observe volume changes while the view is active.
        // Only update the stored value — don't re-trigger the warning overlay
        // because audio session category changes fire spurious volume notifications
        // that would cause the warning to flash repeatedly.
        volumeObserver = NotificationCenter.default.addObserver(
            forName: NSNotification.Name("AVSystemController_SystemVolumeDidChangeNotification"),
            object: nil,
            queue: .main
        ) { [weak viewModel] notification in
            // Skip spurious volume notifications during TTS audio session category changes —
            // each category switch fires volume notifications that cause the UI to "spaz".
            guard viewModel?.isTTSActive != true, SharedStorage.isTTSActive != true else { return }

            // Private system notification includes a reason string.
            // Only react to explicit hardware/software user volume changes.
            if let reason = notification.userInfo?["AVSystemController_AudioVolumeChangeReasonNotificationParameter"] as? String,
               reason != "ExplicitVolumeChange" {
                return
            }

            if let userInfo = notification.userInfo,
               let volumeValue = userInfo["AVSystemController_AudioVolumeNotificationParameter"] as? Float {
                let now = CFAbsoluteTimeGetCurrent()
                // Coalesce volume notifications; iOS can emit bursts around session changes.
                if now - self.lastVolumeNotificationTime < 0.10,
                   abs(volumeValue - self.lastObservedVolume) < 0.02 {
                    return
                }
                self.lastVolumeNotificationTime = now
                self.lastObservedVolume = volumeValue
                self.currentVolume = volumeValue
            }
        }
    }

