        private func startVibrateLoop() {
            // Run a quick burst of shakes, then pause, then repeat
            func shakeBurst() {
                let shakeCount = 6
                let shakeDuration: Double = 0.04
                for i in 0..<shakeCount {
                    DispatchQueue.main.asyncAfter(deadline: .now() + Double(i) * shakeDuration) {
                        withAnimation(.linear(duration: shakeDuration)) {
                            vibrateOffset = (i % 2 == 0) ? 3 : -3
                        }
                    }
                }
                // Return to center after burst
                DispatchQueue.main.asyncAfter(deadline: .now() + Double(shakeCount) * shakeDuration) {
                    withAnimation(.linear(duration: shakeDuration)) {
                        vibrateOffset = 0
                    }
                }
            }

            // Initial burst
            shakeBurst()
            // Repeat every 2 seconds
            shakeTimer = Timer.scheduledTimer(withTimeInterval: 2.0, repeats: true) { _ in
                shakeBurst()
            }
        }

        private func startShimmerLoop() {
            withAnimation(.easeInOut(duration: 1.0)) {
                shimmerOffset = 200
            }
            // Repeat shimmer
            shimmerTimer = Timer.scheduledTimer(withTimeInterval: 2.5, repeats: true) { _ in
                shimmerOffset = -200
                withAnimation(.easeInOut(duration: 1.0)) {
                    shimmerOffset = 200
                }
            }
        }

        func invalidateTimers() {
            shakeTimer?.invalidate()
            shakeTimer = nil
            shimmerTimer?.invalidate()
            shimmerTimer = nil
        }
    }

