import SwiftUI

/// Arc-shaped waveform visualization with 7 bars responding to audio levels
struct ArcWaveformView: View {
    let levels: [CGFloat]  // Array of 7 levels (0.0 to 1.0)
    let maxHeight: CGFloat
    let color: Color
    let arcWidth: CGFloat

    init(
        levels: [CGFloat],
        maxHeight: CGFloat = 32,
        color: Color = .white.opacity(0.5),
        arcWidth: CGFloat = 160
    ) {
        self.levels = levels
        self.maxHeight = maxHeight
        self.color = color
        self.arcWidth = arcWidth
    }

    var body: some View {
        HStack(alignment: .bottom, spacing: 6) {
            ForEach(0..<7, id: \.self) { index in
                WaveformBar(
                    level: levels.indices.contains(index) ? levels[index] : 0.0,
                    maxHeight: maxHeight,
                    barIndex: index,
                    color: color
                )
            }
        }
        .frame(width: arcWidth, height: maxHeight)
        .drawingGroup() // Composites all 7 blur layers into a single offscreen pass
    }
}

/// Individual bar in the waveform
private struct WaveformBar: View {
    let level: CGFloat
    let maxHeight: CGFloat
    let barIndex: Int
    let color: Color

    // Create arc effect - center bars are naturally taller
    private var arcMultiplier: CGFloat {
        // Index 3 is center (highest), edges are lower
        let centerDistance = abs(CGFloat(barIndex - 3))
        return 1.0 - (centerDistance * 0.1)
    }

    private var barHeight: CGFloat {
        let minHeight: CGFloat = 8  // Increased from 4
        let calculatedHeight = max(minHeight, level * maxHeight * arcMultiplier)
        return min(calculatedHeight, maxHeight)
    }

    var body: some View {
        ZStack {
            // Glow layer
            RoundedRectangle(cornerRadius: 3)
                .fill(color.opacity(0.5))
                .frame(width: 6, height: barHeight)
                .blur(radius: 3)

            // Main bar
            RoundedRectangle(cornerRadius: 3)
                .fill(color)
                .frame(width: 6, height: barHeight)  // Increased from 4
        }
        .animation(.easeOut(duration: 0.08), value: level)
    }
}

